      "causa_raiz": "Uso repetitivo de GameObject.FindObjectsOfType<GameObject>() a cada frame dentro do método Update(). Esse método percorre todos os objetos ativos na memória da cena de forma síncrona na CPU, além de alocar novos arrays no heap a cada iteração, gerando picos de processamento acima de 41ms.",
      "codigo_refatorado": "using System;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n        public GameObject testPrefab;\\n\\n        [Range(1, 20)]\\n        public float spawnRadius = 10f;\\n\\n        [Range(1, 50)]\\n        public int cubesPerFrame = 1;\\n\\n        public bool useUniqueMaterials = false;\\n\\n        [Range(1, 512)]\\n        public int cpuScansPerFrame = 1;\\n\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n\\n        [Range(0, 2000)]\\n        public int prepopulateCount = 0;\\n\\n        private MaterialPropertyBlock _propertyBlock;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\\\"_Color\\\");\\n        private StringBuilder _sb = new StringBuilder(4096);\\n        private GameObject[] _cachedObjects = Array.Empty<GameObject>();\\n\\n        private void Awake()\\n        {\\n            _propertyBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                new GameObject(string.Concat(\\\"Empty_\\\", i.ToString()));\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n\\n            CacheSceneObjects();\\n        }\\n\\n        private void CacheSceneObjects()\\n        {\\n            _cachedObjects = FindObjectsByType<GameObject>(FindObjectsSortMode.None);\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + (i * 0.001f);\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                Destroy(quad.GetComponent<Collider>());\\n                quad.name = string.Concat(\\\"Overdraw_\\\", i.ToString());\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _sb.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _sb.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                // Utiliza a lista já armazenada em cache para evitar busca recursiva por toda a hierarquia a cada frame\\n                int count = _cachedObjects.Length;\\n                for (int k = 0; k < cpuScansPerFrame; k++)\\n                {\\n                    for (int j = 0; j < count; j++)\\n                    {\\n                        var obj = _cachedObjects[j];\\n                    }\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);\\n\\n            if (useUniqueMaterials)\\n            {\\n                var rend = clone.GetComponent<Renderer>();\\n                if (rend != null)\\n                {\\n                    rend.GetPropertyBlock(_propertyBlock);\\n                    _propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));\\n                    rend.SetPropertyBlock(_propertyBlock);\\n                }\\n            }\\n        }\\n    }\\n}\",\n      "
      ,"explicacao_didatica": "Procurar objetos em toda a cena usando FindObjectsOfType repetidamente em cada frame é como ler uma lista telefônica inteira do início ao fim 60 vezes por segundo: o processador fica sobrecarregado apenas lendo essa lista. A solução é salvar essa lista uma única vez (fazer cache) e apenas consultá-la quando necessário."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Concatenação de texto usando o operador '+=' em laço e alocação contínua de novos arrays a cada frame gerando mais de 7.7MB de lixo por frame. Isso ativa o Garbage Collector do Unity, travando a thread principal por mais de 11ms.",
      "codigo_refatorado": "using System;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n        public GameObject testPrefab;\\n\\n        [Range(1, 20)]\\n        public float spawnRadius = 10f;\\n\\n        [Range(1, 50)]\\n        public int cubesPerFrame = 1;\\n\\n        public bool useUniqueMaterials = false;\\n\\n        [Range(1, 512)]\\n        public int cpuScansPerFrame = 1;\\n\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n\\n        [Range(0, 2000)]\\n        public int prepopulateCount = 0;\\n\\n        private MaterialPropertyBlock _propertyBlock;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\\\"_Color\\\");\\n        private StringBuilder _sb = new StringBuilder(4096);\\n        private GameObject[] _cachedObjects = Array.Empty<GameObject>();\\n\\n        private void Awake()\\n        {\\n            _propertyBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                new GameObject(string.Concat(\\\"Empty_\\\", i.ToString()));\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n\\n            _cachedObjects = FindObjectsByType<GameObject>(FindObjectsSortMode.None);\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _sb.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _sb.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                int count = _cachedObjects.Length;\\n                for (int k = 0; k < cpuScansPerFrame; k++)\\n                {\\n                    for (int j = 0; j < count; j++)\\n                    {\\n                        var obj = _cachedObjects[j];\\n                    }\\n                }\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);\\n\\n            if (useUniqueMaterials)\\n            {\\n                var rend = clone.GetComponent<Renderer>();\\n                if (rend != null)\\n                {\\n                    rend.GetPropertyBlock(_propertyBlock);\\n                    _propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));\\n                    rend.SetPropertyBlock(_propertyBlock);\\n                }\\n            }\\n        }\\n    }\\n}\",\n      "
      ,"explicacao_didatica": "Textos (strings) no Unity não podem ser modificados depois de criados. Quando você junta palavras com '+', uma nova palavra inteira é alocada e a anterior vira lixo. Fazer isso milhares de vezes por frame enche a memória muito rápido, forçando o Coletor de Lixo (GC) a pausar o jogo inteiro para limpar a bagunça. Usar StringBuilder reaproveita o mesmo espaço na memória sem gerar lixo."
    }
  ],
  "dicas_level_design": null
}

